#!/usr/bin/env python3
"""Self-extracting main.py installer for Wall St Bots backend.
Run this in Cloud Shell: python3 install_main.py
"""
import gzip, base64, os

DATA = ""

output_path = os.path.expanduser("~/Backend/main.py")
os.makedirs(os.path.dirname(output_path), exist_ok=True)

decoded = base64.b64decode(DATA)
content = gzip.decompress(decoded)

with open(output_path, "wb") as f:
    f.write(content)

print(f"Written {len(content)} bytes to {output_path}")
print(f"Lines: {content.count(chr(10).encode()[0])}")

# Verify
import ast
try:
    ast.parse(content)
    print("AST parse: OK - file is valid Python")
except SyntaxError as e:
    print(f"AST ERROR: {e}")
